package org.eclipse.rdf4j.query.algebra.evaluation.impl.evaluationsteps.values;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.BooleanLiteral;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.QueryEvaluationException;
import org.eclipse.rdf4j.query.algebra.And;
import org.eclipse.rdf4j.query.algebra.FunctionCall;
import org.eclipse.rdf4j.query.algebra.QueryModelNode;
import org.eclipse.rdf4j.query.algebra.ValueConstant;
import org.eclipse.rdf4j.query.algebra.evaluation.QueryValueEvaluationStep;
import org.eclipse.rdf4j.query.algebra.evaluation.QueryValueEvaluationStep.ConstantQueryValueEvaluationStep;
import org.eclipse.rdf4j.query.algebra.evaluation.ValueExprEvaluationException;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.junit.jupiter.api.Test;

class LogicalValueEvaluationStepEffectsTest {

	@Test
	void rightFalseRetainsEveryReachableLeftEvaluationWithOrWithoutAlgebra() {
		for (boolean withAlgebra : List.of(false, true)) {
			AtomicInteger calls = new AtomicInteger();
			QueryValueEvaluationStep left = bindings -> {
				calls.incrementAndGet();
				return BooleanLiteral.TRUE;
			};
			QueryModelNode algebra = new And(new FunctionCall("urn:test:volatile-left"),
					new ValueConstant(BooleanLiteral.FALSE));
			QueryValueEvaluationStep step = withAlgebra
					? AndValueEvaluationStep.supply(left, constant(BooleanLiteral.FALSE), algebra)
					: AndValueEvaluationStep.supply(left, constant(BooleanLiteral.FALSE));
			assertThat(step.isConstant()).isFalse();
			assertThat(calls).hasValue(0);
			for (int row = 1; row <= 3; row++) {
				assertThat(step.evaluate(EmptyBindingSet.getInstance())).isEqualTo(BooleanLiteral.FALSE);
				assertThat(calls).hasValue(row);
			}
		}
	}

	@Test
	void rightFalseStillEvaluatesALeftExpressionErrorForEveryRow() {
		AtomicInteger calls = new AtomicInteger();
		QueryValueEvaluationStep left = bindings -> {
			calls.incrementAndGet();
			throw new ValueExprEvaluationException("row-local error");
		};
		QueryValueEvaluationStep step = AndValueEvaluationStep.supply(left, constant(BooleanLiteral.FALSE));
		for (int row = 1; row <= 3; row++) {
			assertThat(step.evaluate(EmptyBindingSet.getInstance())).isEqualTo(BooleanLiteral.FALSE);
			assertThat(calls).hasValue(row);
		}
	}

	@Test
	void decisiveRightValuesCannotSuppressAReachableQueryFatalError() {
		AtomicInteger calls = new AtomicInteger();
		QueryValueEvaluationStep left = bindings -> {
			calls.incrementAndGet();
			throw new QueryEvaluationException("query-fatal error");
		};
		List<QueryValueEvaluationStep> steps = List.of(
				AndValueEvaluationStep.supply(left, constant(BooleanLiteral.FALSE)),
				new OrValueEvaluationStep(left, constant(BooleanLiteral.TRUE)));
		for (QueryValueEvaluationStep step : steps) {
			assertThatThrownBy(() -> step.evaluate(EmptyBindingSet.getInstance()))
					.isInstanceOf(QueryEvaluationException.class)
					.hasMessage("query-fatal error");
		}
		assertThat(calls).hasValue(2);
	}

	@Test
	void rightTrueRetainsReachableOrEvaluation() {
		AtomicInteger calls = new AtomicInteger();
		QueryValueEvaluationStep left = bindings -> {
			calls.incrementAndGet();
			return BooleanLiteral.FALSE;
		};
		QueryValueEvaluationStep step = new OrValueEvaluationStep(left, constant(BooleanLiteral.TRUE));
		for (int row = 1; row <= 3; row++) {
			assertThat(step.evaluate(EmptyBindingSet.getInstance())).isEqualTo(BooleanLiteral.TRUE);
			assertThat(calls).hasValue(row);
		}
	}

	@Test
	void decisiveLeftValuesKeepTheRightOperandUnreachable() {
		AtomicInteger calls = new AtomicInteger();
		QueryValueEvaluationStep right = bindings -> {
			calls.incrementAndGet();
			throw new QueryEvaluationException("unreachable error");
		};
		QueryValueEvaluationStep conjunction = AndValueEvaluationStep.supply(constant(BooleanLiteral.FALSE), right);
		assertThat(conjunction.isConstant()).isTrue();
		assertThat(conjunction.evaluate(EmptyBindingSet.getInstance())).isEqualTo(BooleanLiteral.FALSE);
		assertThat(new OrValueEvaluationStep(constant(BooleanLiteral.TRUE), right)
				.evaluate(EmptyBindingSet.getInstance())).isEqualTo(BooleanLiteral.TRUE);
		assertThat(calls).hasValue(0);
	}

	@Test
	void constantConjunctionsKeepSafeFoldingIncludingEbvErrorAndFalse() {
		for (Value left : List.of(BooleanLiteral.TRUE, BooleanLiteral.FALSE,
				SimpleValueFactory.getInstance().createIRI("urn:ebv-error"))) {
			QueryValueEvaluationStep step = AndValueEvaluationStep.supply(constant(left),
					constant(BooleanLiteral.FALSE));
			assertThat(step.isConstant()).isTrue();
			assertThat(step.evaluate(EmptyBindingSet.getInstance())).isEqualTo(BooleanLiteral.FALSE);
		}
		QueryValueEvaluationStep trueStep = AndValueEvaluationStep.supply(constant(BooleanLiteral.TRUE),
				constant(BooleanLiteral.TRUE));
		assertThat(trueStep.isConstant()).isTrue();
		assertThat(trueStep.evaluate(EmptyBindingSet.getInstance())).isEqualTo(BooleanLiteral.TRUE);
	}

	@Test
	void logicalStepsKeepTheCompleteErrorTablesForConstantAndDynamicOperands() {
		for (boolean constants : List.of(false, true)) {
			for (Operand left : Operand.values()) {
				for (Operand right : Operand.values()) {
					Outcome and = left == Operand.FALSE || right == Operand.FALSE ? Outcome.FALSE
							: left.error || right.error ? Outcome.ERROR : Outcome.TRUE;
					Outcome or = left == Operand.TRUE || right == Operand.TRUE ? Outcome.TRUE
							: left.error || right.error ? Outcome.ERROR : Outcome.FALSE;
					assertOutcome(AndValueEvaluationStep.supply(left.step(constants), right.step(constants)), and);
					assertOutcome(new OrValueEvaluationStep(left.step(constants), right.step(constants)), or);
				}
			}
		}
	}

	private static void assertOutcome(QueryValueEvaluationStep step, Outcome outcome) {
		if (outcome == Outcome.ERROR) {
			assertThatThrownBy(() -> step.evaluate(EmptyBindingSet.getInstance()))
					.isInstanceOf(ValueExprEvaluationException.class);
		} else {
			assertThat(step.evaluate(EmptyBindingSet.getInstance()))
					.isEqualTo(BooleanLiteral.valueOf(outcome == Outcome.TRUE));
		}
	}

	private static QueryValueEvaluationStep constant(Value value) {
		return new ConstantQueryValueEvaluationStep(value);
	}

	private enum Outcome {
		TRUE,
		FALSE,
		ERROR
	}

	private enum Operand {
		TRUE(BooleanLiteral.TRUE, false),
		FALSE(BooleanLiteral.FALSE, false),
		EBV_ERROR(SimpleValueFactory.getInstance().createIRI("urn:ebv-error"), true),
		EXPRESSION_ERROR(null, true);

		private final Value value;
		private final boolean error;

		Operand(Value value, boolean error) {
			this.value = value;
			this.error = error;
		}

		private QueryValueEvaluationStep step(boolean constants) {
			if (this == EXPRESSION_ERROR) {
				return new QueryValueEvaluationStep.Fail("row-local error");
			}
			return constants ? constant(value) : bindings -> value;
		}
	}
}
